    css.push_str(".button{position:relative}.button>[data-dowe-button-content]>[data-dowe-button-icon-start],.button>[data-dowe-button-content]>[data-dowe-button-icon-end]{display:inline-flex;flex:0 0 auto;align-items:center;justify-content:center}.button>[data-dowe-button-content]>[data-dowe-button-icon-start]>.svg,.button>[data-dowe-button-content]>[data-dowe-button-icon-end]>.svg{width:1.5rem;height:1.5rem}.button.is-loading>[data-dowe-button-content]{visibility:hidden}.button>[data-dowe-button-loading]{position:absolute;inset:0;display:inline-flex;align-items:center;justify-content:center}.button>[data-dowe-button-loading][hidden]{display:none}.button>[data-dowe-button-loading]>.svg{width:1.5rem;height:1.5rem}.button:disabled,.button[aria-disabled=\"true\"]{cursor:not-allowed;pointer-events:none}.button.is-disabled,.button[aria-disabled=\"true\"]{opacity:.5}");
